int check_pmd_entry(pmd_t *pmd) {
    pmd_t pmd_val;

    pmd_val = *pmd;
    barrier(); // Compiler barrier to prevent reordering

    if (pmd_none(pmd_val) || pmd_trans_huge(pmd_val) || pmd_bad(pmd_val)) {
        if (pmd_bad(pmd_val)) {
            pmd_set_bad(pmd);
        }
        return 1;
    }

    return 0;
}

